"use strict";

const embeddedImages = {
  logo: "data:image/png;base64,",
  blackBag: "data:image/jpeg;base64,",
  whiteBag: "data:image/jpeg;base64,",
  whatsapp: "data:image/png;base64,",
  instagram: "data:image/png;base64,"
};

document.querySelectorAll("img[data-image]").forEach((image) => {
  image.src = embeddedImages[image.dataset.image];
});

document.querySelectorAll('a[href^="#"]').forEach((link) => {
  link.addEventListener("click", (event) => {
    const destination = document.querySelector(link.getAttribute("href"));
    if (!destination) return;
    event.preventDefault();
    destination.scrollIntoView({ behavior: "smooth" });
  });
});
